from review import card,save,DATE

def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

i='TCS-2659';_,c=card(i);refs=c['references'];refs[0]['locator']='CCC 2022, article 10: Definitions 10–12, Corollary 21, Open Problem 22 and Section 6 read. The target is λ≤(2/√d)(1+d^c), c<0, for the ℓ₂–ℓ∞–ℓ₂ trilinear norm; it is not an ordinary graph eigenvalue bound.'
refs.extend([dict(id='full',title='New Near-Linear Time Decodable Codes Closer to the GV Bound — full version',authors='Guy Blanc, Dean Doron',year=2022,url='https://eccc.weizmann.ac.il/report/2022/027/',locator='Revision 1, 27 March 2022: Open Problem 1 and Section 6 read. Retains “sufficiently dense” without defining the permitted gaps in family sizes; the symmetrization discussion permits duplicate hyperedges.'),dict(id='gray2026',title='Wide Replacement Products Meet Gray Codes: Toward Optimal Small-Bias Sets',authors='Gil Cohen, Itay Cohen',year=2026,url='https://doi.org/10.4230/LIPIcs.CCC.2026.21',locator='CCC 2026, article 21: abstract and Section 1.4 read. Gives an explicit improvement in small-bias sets by a different construction, and explicitly says that the hypergraphs needed for the Blanc–Doron approach still have no known explicit construction.')])
issue='The source does not quantify “sufficiently dense” for the infinite family: the permitted vertex counts, their gaps, and their dependence on degree must be specified. It also does not give a complete uniform input/output and running-time requirement for the hypergraph constructor across degrees. Requiring all n,d, constant-factor gaps, or a polylogarithmic neighbor oracle would each add a condition not stated in Open Problem 22.'
save(i,dict(title='Explicit nearly Ramanujan 3-uniform hypergraphs',formal='Construct an explicit infinite family of d-regular 3-uniform hypergraphs satisfying λ≤(2/√d)(1+d^c) for some absolute constant c<0, with sufficiently dense available sizes for the coding applications in the source. Here λ is defined by the trilinear spectral inequality below. The source leaves the family-density and full uniform construction requirements unspecified.',definitions='The source uses ordered triples: a hypergraph has vertex set V={1,…,n} and a collection E of triples (i,j,k)∈V³. It is d-regular if each vertex occurs exactly d times in each of the three coordinate positions, so |E|=nd. Repeated coordinates are allowed; multiplicities, when present as in the source’s symmetrization, are counted in degrees and sums. For x,y,z∈ℝⁿ define T_H(x,y,z)=d^{−1}Σ_{(i,j,k)∈E}xᵢyⱼzₖ−n^{−2}(Σᵢxᵢ)(Σⱼyⱼ)(Σₖzₖ). The hypergraph is λ-spectral if |T_H(x,y,z)|≤λ‖x‖₂‖y‖∞‖z‖₂ for every x,y,z. Euclidean norms on the first and third vectors and the maximum absolute coordinate on the middle vector are essential. The normalized target is 2d^{−1/2}(1+d^c); as d increases, d^c tends to zero. The exponent c is a fixed constant, independent of n and d, and no particular negative value is prescribed. Explicitness calls for a deterministic construction rather than selecting a favorable random hypergraph; the source contrasts it with stronger local-access explicitness but does not fully specify the family’s uniformity and size coverage.',question_type='yes_no',answer_criterion='A complete formulation must specify the available (n,d) pairs, quantitative density of sizes, uniform construction input and output, and deterministic running-time bound. It then requires a constructor whose outputs satisfy coordinatewise regularity and the displayed spectral bound with one fixed c<0, or a refutation under those same conventions. A randomized existence result, ordinary graph expansion or an ℓ₂–ℓ₂–ℓ₂ hypergraph estimate does not meet this target.',context_blocks=[b('The hyperedges encode a three-way sampling rule','A triple selects three vertices, with every coordinate having a uniform marginal because of regularity. The centered trilinear form measures its deviation from three independent uniform choices.', 'primary'),b('The middle norm is deliberate','The source uses ‖y‖∞, not a Euclidean norm divided by √n. Replacing that norm changes the expansion requirement and can make the desired sparsity regime impossible.', 'primary'),b('Random constructions do not supply the requested family','The source gives a probabilistic construction with mixing parameter O(1/√d), and converts mixing to spectral control with a logarithmic loss. The requested near-2 leading constant and deterministic construction are additional demands.', 'primary'),b('The coding consequence motivates this exact target','Suitable hypergraphs would yield efficiently decodable balanced binary codes with rate near ε² up to logarithmic factors, and corresponding small-bias distributions.', 'primary'),b('The 2026 small-bias improvement does not provide these hypergraphs','The later paper improves explicit small-bias sets through a different construction. Its related-work discussion still identifies the needed explicit hypergraphs as unavailable.', 'gray2026'),b('Remaining specification',issue)],why='Would provide a sparse deterministic sampling object strong enough to improve the parameters of decodable binary codes and small-bias spaces near the Gilbert–Varshamov regime.',references=refs,progress=[dict(date='2022',text='The source obtains randomized mixing hypergraphs and proposes the explicit near-Ramanujan spectral family as Open Problem 22.',citation='primary'),dict(date='2026',text='CCC 2026 improves explicit small-bias sets by another construction and still records the absence of the required explicit hypergraphs.',citation='gray2026')],status='source_open',status_note='Recovered the exact spectral definition and negative exponent from the conference and March 2022 full versions. The CCC 2026 related-work discussion explicitly preserves the missing-construction issue. The quantitative family-density requirement remains unspecified.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered the ordered-triple model, ℓ₂–ℓ∞–ℓ₂ norm and negative exponent without inventing the density of sizes.']),importance=imp(c,'A pseudorandom hypergraph construction with concrete consequences for near-optimal small-bias distributions and decodable codes.'),review_note='Repaired 2/√d and c<0, recovered all spectral normalizations, and distinguished ordered triples from simple unordered hypergraphs. Checked the explicit 2026 discussion and kept the undefined family-density requirement visible.',working_summary=sm(['The desired hypergraphs use ordered triples with uniform marginals in every coordinate.','Their three-way deviation from independent sampling must satisfy a specific ℓ₂–ℓ∞–ℓ₂ inequality.','The target parameter is at most (2/√d)(1+d^c) for a fixed negative c.','Such deterministic families would strengthen constructions of decodable codes and small-bias sets; a 2026 paper still records their absence.','The required density of available sizes and uniform construction interface need specification.'],['primary','full','gray2026'])),notes=['Restored λ≤(2/√d)(1+d^c) with fixed c<0.','Defined ordered triples, coordinatewise regularity and the exact trilinear norm.','Checked the 2026 paper’s explicit statement that this construction remains missing.','Left family-density and construction-uniformity choices unresolved.'],checked_sources=[r['url'] for r in refs],state='improved_unfinished')

i='TCS-2663';_,c=card(i);refs=c['references'];refs[0]['locator']='ITCS 2022, article 116: Definitions 6–7, Proposition 8 and Open Problem 9 read. Restored output length, advice, query count, exact reconstruction and default distinguishing error 1/10.'
refs.extend([dict(id='full2023',title='On Hardness Assumptions Needed for “Extreme High-End” PRGs and Fast Derandomization — full version',authors='Ronen Shaltiel, Emanuele Viola',year=2023,url='https://arxiv.org/abs/2311.11663',locator='20 November 2023, only arXiv v1; also ECCC TR21-153 revision 1. Definitions 1.1 and 1.6–1.7, Proposition 1.8, Open Problem 1.9 and Section 1.3 read. Retains the black-box existence question and explicitly imposes no efficiency on the construction map.'),dict(id='lunch2025',title='Towards Free Lunch Derandomization from Necessary Assumptions (And OWFs)',authors='Marshall Ball, Lijie Chen, Roei Tell',year=2025,url='https://doi.org/10.4230/LIPIcs.CCC.2025.31',locator='CCC 2025, article 31: abstract and introductory model discussion read. Concerns targeted generators and heuristic derandomization over efficiently samplable distributions, with additional hardness assumptions; does not assert the universal black-box reconstruction statement of Open Problem 1.9.')])
issue='The exponent-level notation a=m^{1+o(1)}=2^{(1−o(1))ℓ} does not quantify the required slack between advice length a and the full truth-table length 2^ℓ. Proposition 1.8 motivates the question through useful hardness transfer with a+qm below the available circuit hardness, but Open Problem 9 does not prescribe that slack as part of its standalone parameter list. A precise nondegenerate benchmark must state this additional quantitative convention; it must not silently fix a≤2^ℓ/10 or another arbitrary margin.'
save(i,dict(title='An extreme high-end black-box hardness-to-randomness proof',formal='Do there exist black-box construction/reconstruction pairs (Con_ℓ,Red_ℓ) with seed length r=(1+o(1))ℓ, output length m=2^{(1−o(1))ℓ}, advice length a=m^{1+o(1)}=2^{(1−o(1))ℓ}, and worst-case oracle-query count q=m^{o(1)}=2^{o(ℓ)}, such that any distinguisher with advantage greater than 1/10 against Con_ℓ(f) permits exact reconstruction of every Boolean f on ℓ input bits? This recovers the complete parameter list of the source, but the nontrivial slack required for the advice budget still needs specification.',definitions='For integers u,v≥1, let F_{u,v} be all functions {0,1}ᵘ→{0,1}ᵛ. For each input length ℓ, the construction is an arbitrary map Con_ℓ:F_{ℓ,1}→F_{r,m}; write G_f=Con_ℓ(f). No computation-time, circuit-size or oracle-query bound is imposed on this map, and it may depend on the entire truth table of f. A distinguisher is any Boolean function D:{0,1}ᵐ→{0,1}; it breaks G_f if |Pr[D(G_f(U_r))=1]−Pr[D(U_m)=1]|>1/10, where U_t is uniform on {0,1}ᵗ. Red_ℓ is a deterministic oracle procedure receiving x∈{0,1}^ℓ and α∈{0,1}^a, with oracle access only to D. Its correctness condition is ∀f ∀D breaking G_f ∃α ∀x: Red_ℓ^D(x,α)=f(x). The same α serves every x and may depend on f,D; it is not fresh per input. The procedure may make adaptive queries and must halt using at most q queries for every D,α,x, including choices for which correctness is not required. Only queries are charged; unrestricted finite computation and nonuniform dependence on ℓ are allowed in this combinatorial model. The four parameter sequences depend only on ℓ, and all little-o terms tend to zero as ℓ→∞. In particular r/ℓ→1, (log₂m)/ℓ→1, (log₂a)/(log₂m)→1 and (log₂q)/ℓ→0 (with q≥1 permitted as a bound). Exact reconstruction corresponds to worst-case hardness, not merely agreement on most x. The displayed exponent limits alone do not specify how far a must remain below 2^ℓ.',question_type='yes_no',answer_criterion='After fixing the missing quantitative advice-slack convention, give pairs satisfying the same simultaneous parameter bounds and the full ∀f ∀D ∃α ∀x correctness condition, or rule out all such pairs. Failure of one construction family, an average-case reconstruction theorem or a generator targeted to one input is not a complete negative or positive answer to this universal black-box question.',context_blocks=[b('This is a reduction question rather than a hardness assumption','The pair must work for every candidate Boolean function f. Its role is that any successful generator distinguisher can be converted into a procedure computing f exactly, using advice and black-box access to that distinguisher.', 'primary'),b('Every parameter is near a limiting scale','The seed is only slightly longer than ℓ, the output and advice lengths have exponent approaching ℓ, and the reconstruction procedure uses a subpolynomial number of queries in the output length. Dropping any of those requirements changes the source question.', 'primary'),b('Construction efficiency is deliberately absent','The source explicitly allows arbitrary Con maps to make its black-box lower-bound model broad. A positive answer here would be necessary for the proposed derandomization application, but would not by itself give an efficiently computable generator.', 'full2023'),b('Known barriers concern restricted kinds of proofs','The source proves limitations for certain construction properties and hardness-amplification settings. Its November 2023 full version still explicitly leaves the general parameterized black-box question open.', 'full2023'),b('Later fast derandomization has a different guarantee','The 2025 paper obtains targeted generators under hardness conditions over samplable distributions. That progress does not claim this single construction map and exact reconstruction guarantee for all candidate f and all breaking D.', 'lunch2025'),b('Remaining quantitative convention',issue)],why='Tests the possibility of hardness-to-randomness reductions near their limiting seed and output scales, with a query cost small enough to preserve strong circuit hardness.',references=refs,progress=[dict(date='2022',text='Open Problem 9 asks for the four simultaneous parameters; the paper proves partial barriers rather than a general impossibility theorem.',citation='primary'),dict(date='2023-11-20',text='The full version retains the question as Open Problem 1.9 and clarifies that black-boxness does not enforce construction efficiency.',citation='full2023'),dict(date='2025',text='Later targeted-generator work yields different fast-derandomization guarantees under additional hardness assumptions.',citation='lunch2025')],status='source_open',status_note='Checked the conference definition, November 2023 full-version restatement and revision history, plus the 2025 targeted-generator model. No general resolution was located through 12 September 2026. The standalone exponent notation needs a precise nontrivial advice-slack convention before being certified as a benchmark.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered all parameters and the black-box reconstruction quantifiers; identified a missing fine-scale advice condition.']),importance=imp(c,'A basic barrier question for obtaining nearly optimal pseudorandomness from hardness with minimal query loss.'),review_note='Restored the full parameter list and exact oracle/advice model, including unrestricted Con and worst-case reconstruction. Distinguished the original question from explicit generator construction and recent targeted derandomization, and preserved a genuine asymptotic slack ambiguity.',working_summary=sm(['The source asks for a construction that turns any candidate hard Boolean function into a candidate generator.','Every distinguisher breaking that generator must permit exact reconstruction of the original function using a single advice string.','The desired seed, output, advice and query parameters are all specified simultaneously at extreme high-end scales.','The construction map itself is allowed to be computationally unrestricted, and later targeted-generator results do not settle this model.','The required fine-scale gap between the advice budget and the full truth-table length needs an explicit convention.'],['primary','full2023','lunch2025'])),notes=['Recovered all four asymptotic parameters and the default 1/10 distinguishing error.','Defined ∀f ∀D ∃α ∀x reconstruction, adaptive query accounting and unrestricted construction.','Distinguished the black-box combinatorial question from explicit PRGs and targeted derandomization.','Flagged unquantified advice slack instead of inventing a nontrivial parameter restriction.'],checked_sources=[r['url'] for r in refs]+['https://eccc.weizmann.ac.il/report/2021/153/'],state='improved_unfinished')
